"""Monthly report lifecycle: scheduling, generation, storage, approval and email.

* One row per (website, period, kind) — enforced by a unique constraint, so scheduled generation can
  never create duplicates. Generation locks the row (FOR UPDATE SKIP LOCKED), so two workers
  cannot render the same report at once.
* Client reports must be approved before client users can see or receive them. Regenerating a
  report withdraws approval, because its content may have changed.
* Files are written atomically under STORAGE_DIR; paths are generated by the server, never taken
  from user input, and verified to stay inside the storage root when read.
"""
import hashlib
import logging
import os
import uuid
from datetime import UTC, datetime, timedelta
from pathlib import Path

from sqlalchemy import select
from sqlalchemy.dialects.postgresql import insert as pg_insert
from sqlalchemy.orm import Session

from app.config import get_settings
from app.models import Client, MonthlyReport, SystemSetting, Website
from app.notify.senders import NotifierError
from app.notify.service import compose, queue_notification
from app.reports.data import build_snapshot, period_bounds
from app.reports.pdf import render_pdf

log = logging.getLogger("sitewatch.reports")
KINDS = ("client", "technical")
BRANDING_KEYS = ("company_name", "accent_color", "footer_text", "logo_path")


class ReportError(Exception):
    pass


def storage_root() -> Path:
    root = Path(get_settings().storage_dir).resolve()
    root.mkdir(parents=True, exist_ok=True)
    return root


def safe_path(relative: str) -> Path:
    root = storage_root()
    p = (root / relative).resolve()
    if root not in p.parents:
        raise ReportError("Invalid storage path")
    return p


def get_setting(db: Session, key: str, default=None):
    row = db.get(SystemSetting, key)
    return default if row is None or row.value is None else row.value


def set_setting(db: Session, key: str, value, user_id=None) -> None:
    row = db.get(SystemSetting, key)
    if row is None:
        db.add(SystemSetting(key=key, value=value, updated_by=user_id))
    else:
        row.value, row.updated_by = value, user_id


def branding(db: Session) -> dict:
    return {k: get_setting(db, f"branding.{k}") for k in BRANDING_KEYS}


def logo_file(db: Session) -> str | None:
    rel = get_setting(db, "branding.logo_path")
    if not rel:
        return None
    try:
        p = safe_path(rel)
    except ReportError:
        return None
    return str(p) if p.exists() else None


# ---- creation ---------------------------------------------------------------------------

def ensure_rows(db: Session, site: Website, period: str, kinds=KINDS) -> list[uuid.UUID]:
    """Insert report rows that don't exist yet; returns ids of newly created rows."""
    ids = []
    for kind in kinds:
        rid = db.execute(pg_insert(MonthlyReport).values(
            website_id=site.id, period=period, kind=kind, status="generating", approved_for_client=False,
        ).on_conflict_do_nothing(constraint="uq_monthly_reports_period").returning(MonthlyReport.id)).scalar()
        if rid:
            ids.append(rid)
    return ids


def request_generation(db: Session, site: Website, period: str, kind: str, user_id, regenerate: bool) -> list[MonthlyReport]:
    kinds = KINDS if kind == "both" else (kind,)
    ensure_rows(db, site, period, kinds)
    rows = list(db.scalars(select(MonthlyReport).where(MonthlyReport.website_id == site.id,
                                                       MonthlyReport.period == period, MonthlyReport.kind.in_(kinds))))
    for r in rows:
        if r.status == "ready" and not regenerate:
            raise ReportError(f"A {r.kind} report for {period} already exists. Use 'regenerate' to replace it.")
        r.status, r.error, r.generated_by = "generating", None, user_id
        r.approved_for_client, r.approved_by, r.approved_at = False, None, None
    db.flush()
    return rows


def due_period(now: datetime, generation_day: int) -> str | None:
    """The previous calendar month, once the configured day of this month has arrived."""
    if now.day < generation_day:
        return None
    return (now.replace(day=1) - timedelta(days=1)).strftime("%Y-%m")


def schedule_monthly(db: Session, now: datetime | None = None) -> list[uuid.UUID]:
    now = now or datetime.now(UTC)
    period = due_period(now, int(get_setting(db, "reports.generation_day", 2)))
    ids: list[uuid.UUID] = []
    if period is None:
        return ids
    _, period_end = period_bounds(period)
    sites = db.scalars(select(Website).join(Client, Client.id == Website.client_id).where(
        Website.status == "active", Client.is_active.is_(True), Website.created_at < period_end)).unique()
    for site in sites:
        ids += ensure_rows(db, site, period)
    # Re-send rows stuck in "generating" (lost task); the row lock prevents double work.
    ids += [r for r in db.scalars(select(MonthlyReport.id).where(
        MonthlyReport.status == "generating", MonthlyReport.updated_at < now - timedelta(minutes=30))) if r not in ids]
    db.commit()
    return ids


# ---- generation -------------------------------------------------------------------------

def generate(db: Session, report_id, now: datetime | None = None) -> MonthlyReport | None:
    report = db.scalar(select(MonthlyReport).where(MonthlyReport.id == report_id)
                       .with_for_update(skip_locked=True))
    if report is None or report.status != "generating":
        db.rollback()
        return None
    site = db.get(Website, report.website_id)
    try:
        snap = build_snapshot(db, site, report.period, report.kind, now=now, branding=branding(db))
        pdf = render_pdf(snap, logo_file(db))
        rel = f"reports/{site.id}/{report.period}-{report.kind}-{report.id}.pdf"
        path = safe_path(rel)
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".tmp")
        tmp.write_bytes(pdf)
        os.replace(tmp, path)
        old = report.file_path
        report.file_path, report.size_bytes = rel, len(pdf)
        report.file_sha256 = hashlib.sha256(pdf).hexdigest()
        report.data_snapshot, report.status, report.error = snap, "ready", None
        report.generated_at = now or datetime.now(UTC)
        report.generation_count += 1
        if old and old != rel:
            try:
                safe_path(old).unlink(missing_ok=True)
            except ReportError:
                pass
    except Exception as e:  # noqa: BLE001
        log.exception("Report %s failed", report_id)
        report.status, report.error = "failed", f"{type(e).__name__}: {e}"[:1000]
    db.commit()
    return report


def read_file(report: MonthlyReport) -> bytes:
    if not report.file_path or report.status != "ready":
        raise ReportError("Report file is not available")
    p = safe_path(report.file_path)
    data = p.read_bytes()
    if report.file_sha256 and hashlib.sha256(data).hexdigest() != report.file_sha256:
        raise ReportError("Report file failed its integrity check")
    return data


def download_name(report: MonthlyReport, site: Website) -> str:
    safe = "".join(c if c.isalnum() or c in "-." else "-" for c in site.hostname)
    return f"{safe}-{report.period}-{report.kind}-report.pdf"


def report_attachment(db: Session, report_id) -> tuple[str, bytes, str]:
    report = db.get(MonthlyReport, report_id)
    if report is None:
        raise NotifierError("Report no longer exists")
    try:
        return download_name(report, db.get(Website, report.website_id)), read_file(report), "application/pdf"
    except ReportError as e:
        raise NotifierError(str(e)) from None


# ---- approval & email -------------------------------------------------------------------------

def approve(db: Session, report: MonthlyReport, user_id, email: bool) -> int | None:
    if report.kind != "client":
        raise ReportError("Only client reports are approved for client access.")
    if report.status != "ready":
        raise ReportError("The report is not ready.")
    report.approved_for_client, report.approved_by, report.approved_at = True, user_id, datetime.now(UTC)
    if not email:
        return None
    site = db.get(Website, report.website_id)
    period_label = datetime.strptime(report.period, "%Y-%m").strftime("%B %Y")
    _, body = compose("report_available", site, [
        f"The website maintenance report for {period_label} is attached.",
        "It is also available to download from your dashboard.",
    ])
    log_id = queue_notification(
        db, event_type="report_available", website=site,
        dedup_key=f"report:{report.id}:{report.generation_count}:emailed",
        subject=f"[SiteWatch] {period_label} maintenance report: {site.name}", body=body)
    if log_id:
        from app.models import NotificationLog

        entry = db.get(NotificationLog, log_id)
        entry.attachment_report_id = report.id
        report.emailed_at, report.emailed_to = datetime.now(UTC), list(entry.recipients)
    return log_id
